	private static final long POSITIVE_SYNOPSIS_BUDGET_BYTES = 1024L * 1024L;
	private static final String FRONTIER_DIRECTORY_NAME = "frontier-synopsis";

	@Test
	void positiveBudgetWithoutManifestBuildsAndRestartsReady(@TempDir Path dataDirectory) throws Exception {
		assertStartsAndRestartsWithStatus(dataDirectory,
				config(FrontierEstimatorMode.AUTHORITATIVE, POSITIVE_SYNOPSIS_BUDGET_BYTES),
				FrontierSynopsisStatus.READY);

		assertFalse(Files.notExists(dataDirectory.resolve(FRONTIER_DIRECTORY_NAME).resolve("manifest.bin")),
				"positive-budget bootstrap must publish an initial Frontier generation");
	}

	@Test
	void defaultFrontierInitializesLearnedServicesWithoutLegacySketch(@TempDir Path dataDirectory) throws Exception {
		String previousProfile = System.getProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY);
		System.setProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, "safe-cardinality-correction");
		LmdbStore store = new LmdbStore(dataDirectory.toFile(),
				config(FrontierEstimatorMode.AUTHORITATIVE, POSITIVE_SYNOPSIS_BUDGET_BYTES)
						.setSketchEstimatorEnabled(false));
		try {
			store.init();
			LmdbSailStore backingStore = store.getBackingStore();
			assertEquals(null, field(backingStore, "sketchBasedJoinEstimator"));
			assertNotNull(field(backingStore, "filterSelectivityStats"),
					"Frontier filters must learn even when the legacy sketch is disabled");
			assertNotNull(field(backingStore, "operatorFeedbackStats"),
					"Frontier states must be repairable by LEO without the legacy sketch");
		} finally {
			store.shutDown();
			restoreProperty(LeoRolloutProfile.ROLLOUT_PROFILE_PROPERTY, previousProfile);
		}
	}

	@Test
	void datasetBackedTripleSourceExposesOptionalExecutionSnapshotEpoch() throws Exception {
		Method datasetEpoch;
		Method tripleSourceEpoch;
		try {
			datasetEpoch = SailDataset.class.getMethod("getSnapshotEpoch");
			tripleSourceEpoch = SailDatasetTripleTermSource.class.getMethod("getSnapshotEpoch");
		} catch (NoSuchMethodException e) {
			fail("the optimizer triple source must expose the exact execution snapshot epoch when available", e);
			return;
		}
		assertEquals(OptionalLong.class, datasetEpoch.getReturnType());
		assertEquals(OptionalLong.class, tripleSourceEpoch.getReturnType());
		assertFalse(java.lang.reflect.Modifier.isAbstract(datasetEpoch.getModifiers()),
				"non-snapshot stores require a safe empty default");
	}

	@Test
	void offModeStartsAndRestartsWithoutCreatingFrontierDirectory(@TempDir Path dataDirectory) throws Exception {
		assertStartsAndRestartsWithStatus(dataDirectory,
				config(FrontierEstimatorMode.OFF, POSITIVE_SYNOPSIS_BUDGET_BYTES),
				FrontierSynopsisStatus.DISABLED_MODE);

		assertFalse(Files.exists(dataDirectory.resolve(FRONTIER_DIRECTORY_NAME)),
				"OFF mode must not create a Frontier synopsis directory");
	}

	@Test
	void zeroBudgetStartsAndRestartsWithoutCreatingFrontierDirectory(@TempDir Path dataDirectory) throws Exception {
		assertStartsAndRestartsWithStatus(dataDirectory,
				config(FrontierEstimatorMode.AUTHORITATIVE, 0L),
				FrontierSynopsisStatus.DISABLED_ZERO_BUDGET);

		assertFalse(Files.exists(dataDirectory.resolve(FRONTIER_DIRECTORY_NAME)),
				"zero persistent budget must not create a Frontier synopsis directory");
	}

	@Test
	void explicitRebuildPublishesAndRestartsReadyGeneration(@TempDir Path dataDirectory) throws Exception {
		LmdbStoreConfig config = config(FrontierEstimatorMode.AUTHORITATIVE, POSITIVE_SYNOPSIS_BUDGET_BYTES);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		try {
			store.init();
			assertEquals(FrontierSynopsisStatus.READY, frontierSynopsisStatus(store));
			Method rebuild;
			try {
				rebuild = LmdbStore.class.getMethod("rebuildFrontierSynopsis");
			} catch (NoSuchMethodException e) {
				fail("LmdbStore must expose an explicit Frontier base-generation rebuild", e);
				return;
			}
			assertEquals(FrontierSynopsisStatus.READY, rebuild.invoke(store));
			assertEquals(FrontierSynopsisStatus.READY, frontierSynopsisStatus(store));
			assertFalse(Files.notExists(dataDirectory.resolve(FRONTIER_DIRECTORY_NAME).resolve("manifest.bin")));
		} finally {
			store.shutDown();
		}

		LmdbStore restarted = new LmdbStore(dataDirectory.toFile(), config);
		try {
			restarted.init();
			assertEquals(FrontierSynopsisStatus.READY, frontierSynopsisStatus(restarted));
		} finally {
			restarted.shutDown();
		}
	}

	@Test
	void realExplicitAndInferredQueryDatasetsExposeOneNativeEpoch(@TempDir Path dataDirectory) throws Exception {
		LmdbStore store = new LmdbStore(
				dataDirectory.toFile(),
				config(FrontierEstimatorMode.AUTHORITATIVE, POSITIVE_SYNOPSIS_BUDGET_BYTES));
		try {
			store.init();
			LmdbSailStore backingStore = store.getBackingStore();
			try (SailDataset explicit = backingStore.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT);
					SailDataset inferred = backingStore.getInferredSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				OptionalLong explicitEpoch = new SailDatasetTripleTermSource(store.getValueFactory(), explicit)
						.getSnapshotEpoch();
				OptionalLong inferredEpoch = new SailDatasetTripleTermSource(store.getValueFactory(), inferred)
						.getSnapshotEpoch();
				assertFalse(explicitEpoch.isEmpty());
				assertFalse(inferredEpoch.isEmpty());
				assertEquals(explicitEpoch.getAsLong(), inferredEpoch.getAsLong(),
						"one query view may use a persistent synopsis only when both planes share one native epoch");
			}
		} finally {
			store.shutDown();
		}
	}

	private static void assertStartsAndRestartsWithStatus(Path dataDirectory, LmdbStoreConfig config,
			FrontierSynopsisStatus expectedStatus) throws Exception {
		for (int attempt = 0; attempt < 2; attempt++) {
			LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
			boolean initialized = false;
			try {
				assertDoesNotThrow(store::init,
						"Frontier availability must never prevent LMDB store startup");
				initialized = true;
				assertEquals(expectedStatus, frontierSynopsisStatus(store),
						"the backing store must retain the bootstrap classification");
			} finally {
				if (initialized) {
					assertDoesNotThrow(store::shutDown,
							"Frontier lifecycle ownership must not prevent clean LMDB shutdown");
				}
			}
		}
	}

