	private static void restoreProperty(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}

	private static LmdbStoreConfig config(FrontierEstimatorMode mode, long synopsisBudgetBytes) {
		return new LmdbStoreConfig("spoc")
				.setFrontierEstimatorMode(mode)
				.setFrontierSynopsisBudgetBytes(synopsisBudgetBytes);
	}
